def get_square_free_part(n):
    S = 1
    temp_n = n
    d = 2
    while d * d <= temp_n:
        count = 0
        while temp_n % d == 0:
            count += 1
            temp_n //= d
        if count % 2 == 1:
            S *= d
        d += 1
    if temp_n > 1:
        S *= temp_n
    return S

def generator(rng):
    while True:
        b = rng.randint(5, 40)

        val = b*b - 1
        if val <= 0: continue

        S = get_square_free_part(val)

        solutions = set()
        for t in range(2, b):
            for u in range(1, t):
                check_val = S * (t*t - u*u)
                if check_val > 0:
                    sqrt_val = int(math.sqrt(check_val))
                    if sqrt_val * sqrt_val == check_val:
                        solutions.add((t, u))

        if 2 <= len(solutions) <= 10:
            answer = sum(s[0] * b + s[1] for s in solutions)
            return {'b': b, 'answer': answer}

